Here are the unit tests for the `Calculator` class using Python's built-in `unittest` framework.

```python
import unittest

class Calculator:
    def multiply(self, x, y):
        return x * y

class TestCalculator(unittest.TestCase):
    def test_multiply_positive_integers(self):
        calc = Calculator()
        self.assertEqual(calc.multiply(3, 4), 12)

    def test_multiply_negative_integers(self):
        calc = Calculator()
        self.assertEqual(calc.multiply(-2, 5), -10)

    def test_multiply_floats(self):
        calc = Calculator()
        self.assertAlmostEqual(calc.multiply(1.5, 2.0), 3.0)

    def test_multiply_by_zero(self):
        calc = Calculator()
        self.assertEqual(calc.multiply(10, 0), 0)

    def test_multiply_negative_floats(self):
        calc = Calculator()
        self.assertAlmostEqual(calc.multiply(-1.5, -2.0), 3.0)

if __name__ == '__main__':
    unittest.main()
```

